//! Spark family tests: fixture parity against the pinned reference
//! (`testdata/tts_spark/`, regenerated by
//! `tools/gen_spark_fixtures.py`) plus token-map and prompt-unit
//! checks.

use std::path::{Path, PathBuf};

use super::{AudioTokenMaps, GenerateParams, Model, StopReason};

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_spark")
        .join(name)
}

fn read_json(name: &str) -> serde_json::Value {
    let text = std::fs::read_to_string(testdata(name)).expect(name);
    serde_json::from_str(&text).expect(name)
}

fn ids(value: &serde_json::Value) -> Vec<i32> {
    value
        .as_array()
        .expect("id list")
        .iter()
        .map(|v| v.as_i64().expect("i32") as i32)
        .collect()
}

fn open_case(case: &str) -> Model {
    let dir = testdata(case);
    Model::open(&dir).expect("open model")
}

fn token_maps() -> AudioTokenMaps {
    let config = read_json("generate/config.json");
    build_maps(&config["audio_token_maps"])
}

fn build_maps(maps: &serde_json::Value) -> AudioTokenMaps {
    let semantic: Vec<Option<i32>> = maps["semantic"]
        .as_array()
        .expect("semantic ids")
        .iter()
        .map(|v| {
            if v.is_null() {
                None
            } else {
                Some(v.as_i64().unwrap() as i32)
            }
        })
        .collect();
    let global: Vec<Option<i32>> = maps["global"]
        .as_array()
        .expect("global ids")
        .iter()
        .map(|v| {
            if v.is_null() {
                None
            } else {
                Some(v.as_i64().unwrap() as i32)
            }
        })
        .collect();
    AudioTokenMaps::from_ids(&semantic, &global, semantic.len(), global.len()).unwrap()
}

#[test]
fn greedy_scenarios_match_the_reference() {
    let traces = read_json("generate/traces.json");
    let maps = token_maps();
    for scenario in traces["scenarios"].as_array().expect("scenarios") {
        let mut model = open_case(scenario["case"].as_str().unwrap());
        let prompt = ids(&scenario["prompt_ids"]);
        let params: GenerateParams =
            serde_json::from_value(scenario["params"].clone()).expect("params");
        let generated = model
            .generate(
                &maps,
                &prompt,
                &params,
                scenario["seed"].as_u64().unwrap_or(0),
            )
            .unwrap();
        assert_eq!(
            generated.tokens,
            ids(&scenario["tokens"]),
            "scenario {} tokens",
            scenario["name"]
        );
        assert_eq!(
            generated.semantic_codes,
            ids(&scenario["semantic_codes"]),
            "scenario {} semantic",
            scenario["name"]
        );
        assert_eq!(
            generated.global_codes,
            ids(&scenario["global_codes"]),
            "scenario {} global",
            scenario["name"]
        );
        let want_stop = match scenario["stopped_by"].as_str().unwrap() {
            "end_of_text" => StopReason::EndOfText,
            "semantic_end" => StopReason::SemanticEnd,
            _ => StopReason::MaxTokens,
        };
        assert_eq!(
            generated.stopped_by, want_stop,
            "scenario {}",
            scenario["name"]
        );
    }
}

#[test]
fn sampler_math_matches_the_fixed_logit_traces() {
    let traces = read_json("math/traces.json");
    for case in traces["cases"].as_array().expect("cases") {
        let mut logits: Vec<f32> = case["logits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap() as f32)
            .collect();
        if let Some(bias) = case.get("logit_bias") {
            let pairs: Vec<(i32, f32)> = bias
                .as_array()
                .unwrap()
                .iter()
                .map(|p| (p[0].as_i64().unwrap() as i32, p[1].as_f64().unwrap() as f32))
                .collect();
            crate::tts::sampling::apply_logit_bias(&mut logits, &pairs).unwrap();
        }
        if let Some(penalty) = case.get("repetition_penalty") {
            let context = ids(&case["context"]);
            crate::tts::sampling::apply_repetition_penalty(
                &mut logits,
                &context,
                penalty.as_f64().unwrap() as f32,
                case["repetition_context_size"].as_u64().unwrap() as usize,
            )
            .unwrap();
        }
        let logprobs = crate::tts::sampling::log_softmax(&logits);
        let mut filtered = logprobs.clone();
        let top_p = case["top_p"].as_f64().unwrap() as f32;
        if top_p > 0.0 && top_p < 1.0 {
            crate::tts::sampling::apply_top_p(&mut filtered, top_p);
        }
        let top_k = case["top_k"].as_i64().unwrap();
        if top_k > 0 {
            crate::tts::sampling::apply_top_k(&mut filtered, top_k as usize).unwrap();
        }
        let masked = crate::tts::sampling::argmax(&filtered);
        assert_eq!(masked, case["argmax"].as_u64().unwrap() as usize);
        let want: Vec<Option<f32>> = case["filtered"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| {
                if v.is_null() {
                    None
                } else {
                    Some(v.as_f64().unwrap() as f32)
                }
            })
            .collect();
        for (got, want) in filtered.iter().zip(&want) {
            match want {
                None => assert!(got.is_infinite() && *got < 0.0, "expected -inf"),
                Some(w) => assert!((got - w).abs() < 1e-5, "{got} vs {w}"),
            }
        }
    }
}

#[test]
fn prompt_builders_match_the_reference_strings() {
    let traces = read_json("prompts.json");
    assert_eq!(
        Model::process_prompt("Hello there.", Some("Ref voice."), &[5, 9], &[3, 1, 4],),
        traces["clone"]["string"].as_str().unwrap()
    );
    assert_eq!(
        Model::process_prompt("Hello there.", None, &[7], &[]),
        traces["clone_no_text"]["string"].as_str().unwrap()
    );
    assert_eq!(
        Model::process_prompt_control("male", "moderate", "high", "Hello there.").unwrap(),
        traces["control"]["string"].as_str().unwrap()
    );
    assert!(Model::process_prompt_control("robot", "moderate", "high", "Hi").is_err());
    assert!(Model::process_prompt_control("male", "loud", "high", "Hi").is_err());
}

#[test]
fn params_validate() {
    let mut params = GenerateParams::default();
    assert!(params.validate().is_ok());
    params.max_tokens = 0;
    assert!(params.validate().is_err());
    params.max_tokens = 10;
    params.top_k = -1;
    assert!(params.validate().is_err());
    params.top_k = 50;
    params.temperature = -0.1;
    assert!(params.validate().is_err());
}

#[test]
fn token_maps_extract_codes_in_order() {
    let maps = build_maps(&read_json("generate/config.json")["audio_token_maps"]);
    let codes = maps.extract_semantic(&[101, 5, 103, 40, 102]);
    assert_eq!(codes, vec![1, 3, 2]);
    let globals = maps.extract_global(&[41, 101, 42]);
    assert_eq!(globals, vec![1, 2]);
}

#[test]
fn config_refuses_values_that_do_not_fit_their_fields() {
    // `as` casts used to wrap these silently. 2^40 does not fit i32 or u32.
    let mut value = read_json("generate/config.json");
    value["eos_token_id"] = serde_json::json!(1i64 << 40);
    let error = super::ModelConfig::from_json(&value).unwrap_err();
    assert!(error.to_string().contains("does not fit"), "{error}");
    let mut value = read_json("generate/config.json");
    value["sample_rate"] = serde_json::json!(1u64 << 40);
    let error = super::ModelConfig::from_json(&value).unwrap_err();
    assert!(error.to_string().contains("does not fit"), "{error}");
}
